import SceneKit
import AppKit

/// Builds and drives the SceneKit scene of the Lofree Flow 2 (84 keys).
///
/// Geometry comes from `Flow2-84.usdz` (generated by `model/build_flow2.py`, real
/// dimensions in metres, Z up). Materials, lighting, legends and the backlight are
/// set up here so the two finishes and the live state can change without reloading.
final class Flow2Scene {
    enum Finish { case spaceGray, silver }
    enum Camera { case cinematic, top, touchBar, profile }

    struct Key {
        let node: SCNNode
        let material: SCNMaterial
        let halo: SCNMaterial
        let nx: Double          // 0…1 left → right
        let ny: Double          // 0…1 rear → front
        let restZ: CGFloat
    }

    enum LoadError: Error { case missingModel }

    let scene = SCNScene()
    let cameraNode = SCNNode()
    private let board = SCNNode()
    private var model = SCNNode()
    private(set) var keys: [Int: Key] = [:]

    private let aluminum = SCNMaterial()
    private let plate = SCNMaterial()
    private let switches = SCNMaterial()
    private let glass = SCNMaterial()
    private let rubber = SCNMaterial()
    private let portRing = SCNMaterial()
    private let portDark = SCNMaterial()
    private let led = SCNMaterial()

    private let zoneContainer = SCNNode()
    private var touchBarBox: (min: SCNVector3, max: SCNVector3) = (SCNVector3Zero, SCNVector3Zero)
    private var finish: Finish = .spaceGray
    private var selectedKey: Int?
    private var hoveredKey: Int?
    private var markedKeys: Set<Int> = []

    private static let keyTravel: CGFloat = 0.0022          // metres
    private static let horizontalFOV: CGFloat = 30
    private var boundsMin = simd_float3(-17.06, 0, -6.3)    // board extents in scene space (cm)
    private var boundsMax = simd_float3(17.06, 2.02, 6.3)
    private static let zoneColors: [NSColor] = [.systemBlue, .systemIndigo, .systemCyan]

    // MARK: - Loading

    init(resourceDirectory dir: URL) throws {
        let modelURL = dir.appendingPathComponent("Flow2-84.usdz")
        guard FileManager.default.fileExists(atPath: modelURL.path),
              let loaded = try? SCNScene(url: modelURL, options: nil),
              let root = loaded.rootNode.childNode(withName: "Flow2", recursively: true)
        else { throw LoadError.missingModel }

        root.removeFromParentNode()
        root.childNode(withName: "env_light", recursively: false)?.removeFromParentNode()
        root.childNode(withName: "_materials", recursively: false)?.removeFromParentNode()
        model = root

        // Blender space (metres, Z up) → scene space (centimetres, Y up, front towards +Z).
        model.eulerAngles.x = -.pi / 2
        model.scale = SCNVector3(100, 100, 100)
        board.addChildNode(model)
        let (minB, maxB) = board.boundingBox
        board.position.y = -CGFloat(minB.y)
        scene.rootNode.addChildNode(board)
        boundsMin = simd_float3(Float(minB.x), 0, Float(minB.z))
        boundsMax = simd_float3(Float(maxB.x), Float(maxB.y - minB.y), Float(maxB.z))

        let legends = NSImage(contentsOf: dir.appendingPathComponent("legends.png"))
        configureMaterials()
        assignMaterials(legends: legends)
        buildHalos()
        buildTouchZones()
        buildLighting(environment: dir.appendingPathComponent("studio_env.exr"))
        buildCamera()
        apply(finish: .spaceGray)
        setCamera(.cinematic, animated: false)
    }

    // MARK: - Materials

    private static func linear(_ c: Double) -> Double {
        c <= 0.04045 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4)
    }

    private static func vec(_ r: Double, _ g: Double, _ b: Double) -> NSValue {
        NSValue(scnVector3: SCNVector3(CGFloat(linear(r)), CGFloat(linear(g)), CGFloat(linear(b))))
    }

    private static func color(_ r: Double, _ g: Double, _ b: Double) -> NSColor {
        NSColor(srgbRed: r, green: g, blue: b, alpha: 1)
    }

    private func configureMaterials() {
        for m in [aluminum, plate, switches, glass, rubber, portRing, portDark, led] {
            m.lightingModel = .physicallyBased
        }
        aluminum.metalness.contents = 1.0
        aluminum.roughness.contents = 0.40
        plate.roughness.contents = 0.75
        switches.roughness.contents = 0.6
        glass.diffuse.contents = Self.color(0.012, 0.012, 0.016)
        glass.roughness.contents = 0.06
        glass.clearCoat.contents = 1.0
        glass.clearCoatRoughness.contents = 0.03
        rubber.diffuse.contents = Self.color(0.05, 0.05, 0.05)
        rubber.roughness.contents = 0.9
        portRing.diffuse.contents = Self.color(0.86, 0.87, 0.89)
        portRing.metalness.contents = 1.0
        portRing.roughness.contents = 0.14
        portDark.diffuse.contents = Self.color(0.03, 0.03, 0.035)
        portDark.metalness.contents = 0.5
        portDark.roughness.contents = 0.35
        led.diffuse.contents = Self.color(0.02, 0.02, 0.02)
        led.roughness.contents = 0.3
    }

    /// Keycap shading: the legend atlas is a mask; cap and legend colours and the
    /// shine-through glow are uniforms so each key can be tinted and lit on its own.
    private static let keycapShader = """
    #pragma arguments
    float3 capColor;
    float3 legendColor;
    float3 glowColor;
    float glow;
    float skirtGlow;
    #pragma body
    float legendMask = _surface.diffuse.r;
    _surface.diffuse.rgb = mix(capColor, legendColor, legendMask);
    // Height inside the keycap (metres): the skirt catches the LED light from below.
    float h = (scn_node.inverseModelViewTransform * float4(_surface.position, 1.0)).z;
    float skirt = 1.0 - smoothstep(0.0, 0.0050, h);
    // Neighbouring keys shade the lower part of the cap: darker skirts, crisp top edge.
    float occlusion = mix(0.34, 1.0, smoothstep(0.0005, 0.0062, h));
    _surface.diffuse.rgb *= occlusion;
    _surface.ambientOcclusion *= occlusion;
    _surface.emission.rgb = glowColor * (glow * legendMask) + float3(1.0, 0.975, 0.94) * (skirtGlow * skirt * skirt);
    """

    private func makeKeycapMaterial(legends: NSImage?) -> SCNMaterial {
        let m = SCNMaterial()
        m.lightingModel = .physicallyBased
        m.diffuse.contents = legends ?? NSColor.black
        m.diffuse.mipFilter = .linear
        m.diffuse.maxAnisotropy = 8
        m.roughness.contents = 0.56
        m.metalness.contents = 0.0
        // The emission slot must be in use for the modifier's emission to be shaded.
        m.emission.contents = NSColor.white
        m.shaderModifiers = [.surface: Self.keycapShader]
        m.setValue(Self.vec(1.0, 0.975, 0.94), forKey: "glowColor")
        m.setValue(NSNumber(value: 0.0), forKey: "glow")
        m.setValue(NSNumber(value: 0.0), forKey: "skirtGlow")
        return m
    }

    private func assignMaterials(legends: NSImage?) {
        var positions: [(id: Int, node: SCNNode, material: SCNMaterial)] = []
        for part in model.childNodes {
            guard let name = part.name else { continue }
            let material: SCNMaterial
            if name.hasPrefix("key_"), let id = Int(name.dropFirst(4)) {
                material = makeKeycapMaterial(legends: legends)
                positions.append((id, part, material))
            } else if name == "case" || name == "bottom" || (name.hasPrefix("kickstand") && !name.contains("tip")) {
                material = aluminum
            } else if name == "plate" {
                material = plate
            } else if name == "switches" {
                material = switches
            } else if name == "touchbar" {
                material = glass
                touchBarBox = part.boundingBox
            } else if name == "usbc_ring" {
                material = portRing
            } else if name.hasPrefix("usbc") {
                material = portDark
            } else if name == "led" {
                material = led
            } else {
                material = rubber
            }
            part.enumerateHierarchy { node, _ in
                node.geometry?.materials = [material]
                node.castsShadow = true
            }
        }

        let xs = positions.map { Double($0.node.position.x) }
        let ys = positions.map { Double($0.node.position.y) }
        guard let x0 = xs.min(), let x1 = xs.max(), let y0 = ys.min(), let y1 = ys.max() else { return }
        for p in positions {
            let halo = SCNMaterial()
            keys[p.id] = Key(
                node: p.node,
                material: p.material,
                halo: halo,
                nx: (Double(p.node.position.x) - x0) / max(x1 - x0, 1e-6),
                ny: (y1 - Double(p.node.position.y)) / max(y1 - y0, 1e-6),
                restZ: p.node.position.z
            )
        }
    }

    // MARK: - Backlight halos (light leaking around the keycaps)

    /// Soft white frame, brighter towards the rear where the LED of each switch sits.
    private static func haloImage() -> CGImage? {
        let size = 96
        guard let ctx = CGContext(data: nil, width: size, height: size, bitsPerComponent: 8, bytesPerRow: 0,
                                  space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                  bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue) else { return nil }
        let full = CGRect(x: 0, y: 0, width: size, height: size)
        ctx.setFillColor(CGColor(gray: 0, alpha: 1))
        ctx.fill(full)
        ctx.saveGState()
        ctx.setShadow(offset: .zero, blur: 9, color: CGColor(gray: 1, alpha: 1))
        ctx.setFillColor(CGColor(gray: 1, alpha: 1))
        ctx.addPath(CGPath(roundedRect: full.insetBy(dx: 14, dy: 14), cornerWidth: 9, cornerHeight: 9, transform: nil))
        ctx.fillPath()
        ctx.restoreGState()
        ctx.setBlendMode(.multiply)
        let colors = [CGColor(gray: 0.28, alpha: 1), CGColor(gray: 1, alpha: 1)] as CFArray
        if let g = CGGradient(colorsSpace: CGColorSpace(name: CGColorSpace.sRGB)!, colors: colors, locations: [0, 1]) {
            ctx.drawLinearGradient(g, start: CGPoint(x: 0, y: 0), end: CGPoint(x: 0, y: size), options: [])
        }
        return ctx.makeImage()
    }

    private func buildHalos() {
        let image = Self.haloImage()
        for key in keys.values {
            let (mn, mx) = key.node.boundingBox
            let w = CGFloat(mx.x - mn.x) + 0.0034
            let d = CGFloat(mx.y - mn.y) + 0.0034
            let planeGeo = SCNPlane(width: w, height: d)
            let m = key.halo
            m.lightingModel = .constant
            m.diffuse.contents = NSColor.black
            m.emission.contents = image
            m.blendMode = .add
            m.writesToDepthBuffer = false
            m.isDoubleSided = true
            m.transparency = 0
            planeGeo.materials = [m]
            let n = SCNNode(geometry: planeGeo)
            // LEDs sit on the rear side of each switch: the glow is slightly stronger there.
            // At the foot of the keycap: only the part showing in the gaps between keys is visible.
            n.position = SCNVector3(key.node.position.x, key.node.position.y + 0.0006, key.restZ + 0.0003)
            n.castsShadow = false
            n.renderingOrder = 5
            model.addChildNode(n)
        }
    }

    // MARK: - Touch Bar zones

    private func buildTouchZones() {
        zoneContainer.name = "touchzones"
        model.addChildNode(zoneContainer)
    }

    /// Coloured overlays on the side Touch Bar. `visible == false` leaves the bare black glass.
    func setTouchZones(count: Int, b1: Int, b2: Int, active: Int, visible: Bool) {
        zoneContainer.childNodes.forEach { $0.removeFromParentNode() }
        guard visible else { return }
        let f1 = CGFloat(max(5, min(95, b1))) / 100
        let f2 = CGFloat(max(5, min(95, b2))) / 100
        let spans: [(CGFloat, CGFloat)]
        switch count {
        case 3: spans = [(0, min(f1, f2)), (min(f1, f2), max(f1, f2)), (max(f1, f2), 1)]
        case 2: spans = [(0, f1), (f1, 1)]
        default: spans = [(0, 1)]
        }
        let yRear = CGFloat(touchBarBox.max.y), yFront = CGFloat(touchBarBox.min.y)
        let length = yRear - yFront
        let height = CGFloat(touchBarBox.max.z - touchBarBox.min.z)
        let zMid = CGFloat(touchBarBox.max.z + touchBarBox.min.z) / 2
        let gap: CGFloat = 0.0012
        for (i, span) in spans.enumerated() {
            let len = max(0.004, (span.1 - span.0) * length - gap)
            let geo = SCNPlane(width: height * 0.46, height: len)
            geo.cornerRadius = height * 0.23
            let color = Self.zoneColors[i % Self.zoneColors.count]
            let m = SCNMaterial()
            m.lightingModel = .constant
            m.diffuse.contents = NSColor.black
            m.emission.contents = color
            m.emission.intensity = i == active ? 1.6 : 0.45
            m.blendMode = .add
            m.writesToDepthBuffer = false
            geo.materials = [m]
            let n = SCNNode(geometry: geo)
            n.name = "touchzone_\(i)"
            n.eulerAngles.y = .pi / 2
            n.position = SCNVector3(CGFloat(touchBarBox.max.x) + 0.00012,
                                    yRear - (span.0 + span.1) / 2 * length, zMid)
            n.castsShadow = false
            n.renderingOrder = 6
            zoneContainer.addChildNode(n)
        }
    }

    // MARK: - Lighting and camera

    private func buildLighting(environment: URL) {
        scene.background.contents = NSColor.clear
        if FileManager.default.fileExists(atPath: environment.path) {
            scene.lightingEnvironment.contents = environment
        } else {
            scene.lightingEnvironment.contents = NSColor(white: 0.6, alpha: 1)
        }
        scene.lightingEnvironment.intensity = 1.25

        // Key light from the front left: tops catch it, skirts fall off, which gives the keys their relief.
        let key = SCNLight()
        key.type = .directional
        key.intensity = 900
        key.color = Self.color(1.0, 0.985, 0.96)
        key.castsShadow = false
        let keyNode = SCNNode()
        keyNode.light = key
        keyNode.position = SCNVector3(-18, 44, 26)
        keyNode.look(at: SCNVector3(0, 0, 0))
        scene.rootNode.addChildNode(keyNode)

        // Cool rim from the rear right: a thin highlight on the far edges of the caps and the case.
        let rim = SCNLight()
        rim.type = .directional
        rim.intensity = 420
        rim.color = Self.color(0.86, 0.92, 1.0)
        rim.castsShadow = false
        let rimNode = SCNNode()
        rimNode.light = rim
        rimNode.position = SCNVector3(26, 20, -34)
        rimNode.look(at: SCNVector3(0, 0, 0))
        scene.rootNode.addChildNode(rimNode)

        // Soft contact shadow under the board (the view's background stays transparent).
        let shadowGeo = SCNPlane(width: 512 / Self.shadowScale, height: 256 / Self.shadowScale)
        let shadowMat = SCNMaterial()
        shadowMat.lightingModel = .constant
        shadowMat.diffuse.contents = Self.contactShadowImage()
        shadowMat.writesToDepthBuffer = false
        shadowGeo.materials = [shadowMat]
        let shadow = SCNNode(geometry: shadowGeo)
        shadow.eulerAngles.x = -.pi / 2
        shadow.position = SCNVector3(0.5, 0.01, 0.9)
        shadow.castsShadow = false
        shadow.renderingOrder = -10
        scene.rootNode.addChildNode(shadow)
    }

    private static let shadowScale: CGFloat = 9.6      // pixels per centimetre

    private static func contactShadowImage() -> CGImage? {
        let w = 512, h = 256
        guard let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: 0,
                                  space: CGColorSpace(name: CGColorSpace.sRGB)!,
                                  bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { return nil }
        let core = CGRect(x: (CGFloat(w) - 34.12 * shadowScale) / 2, y: (CGFloat(h) - 12.6 * shadowScale) / 2,
                          width: 34.12 * shadowScale, height: 12.6 * shadowScale)
        let far: CGFloat = 4000
        for (blur, alpha, inset) in [(34.0, 0.30, -2.0), (9.0, 0.42, 5.0)] as [(CGFloat, CGFloat, CGFloat)] {
            ctx.saveGState()
            ctx.setShadow(offset: CGSize(width: 0, height: -far), blur: blur, color: CGColor(gray: 0, alpha: alpha))
            ctx.setFillColor(CGColor(gray: 0, alpha: 1))
            let r = core.insetBy(dx: inset, dy: inset).offsetBy(dx: 0, dy: far)
            ctx.addPath(CGPath(roundedRect: r, cornerWidth: 5.5 * shadowScale, cornerHeight: 5.5 * shadowScale, transform: nil))
            ctx.fillPath()
            ctx.restoreGState()
        }
        return ctx.makeImage()
    }

    private func buildCamera() {
        let cam = SCNCamera()
        cam.projectionDirection = .horizontal
        cam.fieldOfView = Self.horizontalFOV
        cam.zNear = 1
        cam.zFar = 1200
        cam.wantsHDR = true
        cam.exposureOffset = -0.25
        cam.minimumExposure = -1
        cam.maximumExposure = 1
        cam.wantsExposureAdaptation = false
        cam.bloomIntensity = 0.28
        cam.bloomThreshold = 1.4
        cam.bloomBlurRadius = 5
        cam.contrast = 0.10
        cam.saturation = 1.04
        // No screen-space AO: with this long lens it hatches the keycaps on 1x displays.
        cameraNode.camera = cam
        scene.rootNode.addChildNode(cameraNode)
    }

    /// A view of the board: where the camera sits relative to its target and what must stay in frame.
    private struct Shot {
        let direction: simd_float3      // from the target towards the camera
        let target: simd_float3
        let up: simd_float3
        let boxMin: simd_float3
        let boxMax: simd_float3
        let margin: Float
    }

    private func shot(for camera: Camera) -> Shot {
        let yUp = simd_float3(0, 1, 0)
        let lo = boundsMin, hi = boundsMax
        switch camera {
        case .cinematic:
            return Shot(direction: simd_float3(19, 40, 58), target: simd_float3(0, 0.9, 0), up: yUp,
                        boxMin: lo, boxMax: hi, margin: 0.90)
        case .top:
            return Shot(direction: simd_float3(0, 1, 0.012), target: simd_float3(0, 1.0, 0), up: simd_float3(0, 0, -1),
                        boxMin: lo, boxMax: hi, margin: 0.90)
        case .touchBar:
            return Shot(direction: simd_float3(35.5, 12.4, 20.2), target: simd_float3(11.5, 0.6, 0.8), up: yUp,
                        boxMin: simd_float3(6, lo.y, lo.z), boxMax: hi, margin: 0.92)
        case .profile:
            return Shot(direction: simd_float3(24, 9.2, 66), target: simd_float3(0, 0.9, 0), up: yUp,
                        boxMin: lo, boxMax: hi, margin: 0.90)
        }
    }

    /// Camera position that keeps the shot's box inside the frustum for the given view aspect ratio.
    func pose(for camera: Camera, aspect: CGFloat) -> (position: SCNVector3, target: SCNVector3, up: SCNVector3) {
        let s = shot(for: camera)
        let d = simd_normalize(s.direction)
        let f = -d
        let r = simd_normalize(simd_cross(f, s.up))
        let u = simd_cross(r, f)
        let th = tan(Float(Self.horizontalFOV) * .pi / 360)
        let tv = th / Float(max(aspect, 0.2))
        var distance: Float = 0
        for i in 0..<8 {
            let c = simd_float3(i & 1 == 0 ? s.boxMin.x : s.boxMax.x,
                                i & 2 == 0 ? s.boxMin.y : s.boxMax.y,
                                i & 4 == 0 ? s.boxMin.z : s.boxMax.z)
            let v = c - s.target
            let z = simd_dot(v, d)
            distance = max(distance, z + abs(simd_dot(v, r)) / (th * s.margin), z + abs(simd_dot(v, u)) / (tv * s.margin))
        }
        let p = s.target + d * distance
        return (SCNVector3(p), SCNVector3(s.target), SCNVector3(s.up))
    }

    @discardableResult
    func setCamera(_ camera: Camera, aspect: CGFloat = 2.4, animated: Bool, duration: Double = 0.8,
                   node: SCNNode? = nil) -> SCNVector3 {
        let target = node ?? cameraNode
        let p = pose(for: camera, aspect: aspect)
        SCNTransaction.begin()
        SCNTransaction.animationDuration = animated ? duration : 0
        SCNTransaction.animationTimingFunction = CAMediaTimingFunction(name: .easeInEaseOut)
        target.position = p.position
        target.look(at: p.target, up: p.up, localFront: SCNVector3(0, 0, -1))
        SCNTransaction.commit()
        return p.position
    }

    // MARK: - State

    func apply(finish: Finish) {
        self.finish = finish
        switch finish {
        case .spaceGray:
            aluminum.diffuse.contents = Self.color(0.56, 0.565, 0.60)
            plate.diffuse.contents = Self.color(0.035, 0.035, 0.04)
            switches.diffuse.contents = Self.color(0.03, 0.03, 0.035)
        case .silver:
            aluminum.diffuse.contents = Self.color(0.67, 0.68, 0.695)
            plate.diffuse.contents = Self.color(0.50, 0.51, 0.52)
            switches.diffuse.contents = Self.color(0.46, 0.47, 0.48)
        }
        for id in keys.keys { tintKey(id) }
    }

    private func tintKey(_ id: Int) {
        guard let key = keys[id] else { return }
        let m = key.material
        let dark = finish == .spaceGray
        var cap = dark ? (0.082, 0.082, 0.088) : (0.70, 0.705, 0.71)
        var legend = dark ? (0.80, 0.80, 0.80) : (0.17, 0.175, 0.19)
        if markedKeys.contains(id) {
            // Remapped keys: the legend takes the accent colour.
            legend = dark ? (1.0, 0.62, 0.16) : (0.80, 0.36, 0.0)
        }
        if id == selectedKey {
            cap = (0.04, 0.42, 0.96)
            legend = (1, 1, 1)
        } else if id == hoveredKey {
            cap = dark ? (0.17, 0.17, 0.185) : (0.82, 0.83, 0.845)
        }
        m.setValue(Self.vec(cap.0, cap.1, cap.2), forKey: "capColor")
        m.setValue(Self.vec(legend.0, legend.1, legend.2), forKey: "legendColor")
        // The backlight shines through the legend: it takes the accent colour too.
        let marked = markedKeys.contains(id) && id != selectedKey
        m.setValue(marked ? Self.vec(1.0, 0.50, 0.08) : Self.vec(1.0, 0.975, 0.94), forKey: "glowColor")
    }

    func setSelectedKey(_ id: Int?) {
        let old = selectedKey
        selectedKey = id
        if let old { tintKey(old) }
        if let id { tintKey(id) }
    }

    /// Pointer feedback: the key under the cursor lifts a shade.
    func setHoveredKey(_ id: Int?) {
        guard id != hoveredKey else { return }
        let old = hoveredKey
        hoveredKey = id
        if let old { tintKey(old) }
        if let id { tintKey(id) }
    }

    /// Keys whose assignment differs from the factory layout.
    func setMarkedKeys(_ ids: Set<Int>) {
        guard ids != markedKeys else { return }
        let changed = ids.symmetricDifference(markedKeys)
        markedKeys = ids
        for id in changed { tintKey(id) }
    }

    /// Short spring press, as when the switch bottoms out.
    func pressKey(_ id: Int) {
        guard let key = keys[id] else { return }
        let down = SCNAction.customAction(duration: 0.07) { node, t in
            node.position.z = key.restZ - Self.keyTravel * min(1, t / 0.07)
        }
        let up = SCNAction.customAction(duration: 0.16) { node, t in
            let k = 1 - min(1, t / 0.16)
            node.position.z = key.restZ - Self.keyTravel * k * k
        }
        key.node.removeAllActions()
        key.node.runAction(.sequence([down, up]))
    }

    func setStatusLED(_ color: NSColor?) {
        if let color {
            led.emission.contents = color
            led.emission.intensity = 2.2
        } else {
            led.emission.contents = NSColor.black
            led.emission.intensity = 0
        }
    }

    /// Per-key backlight: shine-through legends plus the halo between the keycaps.
    /// `brightness` 0…100, `effect` and `speed` follow the firmware's lighting modes.
    func updateBacklight(time: TimeInterval, brightness: Double, effect: Int, speed: Int) {
        let base = max(0.0, min(1.0, brightness / 100.0))
        let speeds = [0.65, 1.25, 2.0, 3.1]
        let sp = speeds[max(0, min(3, speed))]
        // White keycaps: legends stay dark for legibility, only the underglow shows.
        let legendGain = finish == .spaceGray ? 3.0 : 0.0
        let skirtGain = finish == .spaceGray ? 0.30 : 0.22
        let haloGain = finish == .spaceGray ? 0.36 : 0.26
        for key in keys.values {
            let f: Double
            switch effect {
            case 1: f = 0.25 + 0.75 * (0.5 + 0.5 * sin(time * sp * 1.6))
            case 2: f = 0.2 + 0.8 * (0.5 + 0.5 * sin(time * sp * 2.4 - key.ny * 5.0))
            case 3: f = 0.2 + 0.8 * (0.5 + 0.5 * sin(time * sp * 2.4 + key.ny * 5.0))
            case 4:
                let wave = sin(time * sp * 1.4) * 0.5 + 0.5
                f = max(0.15, 1.0 - abs(key.nx - wave) * 2.1)
            case 5: f = 0.3 + 0.7 * (0.5 + 0.5 * sin(time * sp * 2.0 - key.nx * 4.5 - key.ny * 2.0))
            case 6: f = 0.2 + 0.8 * (0.5 + 0.5 * sin(time * sp * 3.0 - key.ny * 6.5 + sin(key.nx * 8.0)))
            default: f = 1.0
            }
            let v = base * f
            key.material.setValue(NSNumber(value: v * legendGain), forKey: "glow")
            key.material.setValue(NSNumber(value: v * skirtGain), forKey: "skirtGlow")
            key.halo.transparency = CGFloat(v * haloGain)
        }
    }

    // MARK: - Hit testing

    enum Hit { case key(Int), touchZone(Int) }

    func resolve(hit node: SCNNode) -> Hit? {
        var current: SCNNode? = node
        while let n = current {
            if let name = n.name {
                if name.hasPrefix("key_"), let id = Int(name.dropFirst(4)) { return .key(id) }
                if name.hasPrefix("touchzone_"), let id = Int(name.dropFirst(10)) { return .touchZone(id) }
                if name == "touchbar" { return .touchZone(0) }
            }
            current = n.parent
        }
        return nil
    }
}
